+++ b/src/main/java/com/example/customers/domain/CustomerFilter.java
@@ -0,0 +1,60 @@
+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * Narrows the customer list by name and by status. A customer matches when it
+ * satisfies both parts.
+ *
+ * <p>The name is split on whitespace into terms, and every term must appear as a
+ * substring of the customer's first name or last name. Case and accents are
+ * ignored on both sides, so {@code makinen} and {@code MAKINEN} both match
+ * {@code Mäkinen}.
+ *
+ * @param name     the text typed into the name filter; blank matches every name
+ * @param statuses the statuses to show; empty shows every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = Set.copyOf(statuses);
+    }
+
+    /** Returns a test for whether a customer satisfies this filter. */
+    public Predicate<Customer> matcher() {
+        List<String> terms = nameTerms();
+        return customer -> (statuses.isEmpty() || statuses.contains(customer.status()))
+                && matchesEveryTerm(customer, terms);
+    }
+
+    private List<String> nameTerms() {
+        return WHITESPACE.splitAsStream(name)
+                .map(CustomerFilter::fold)
+                .filter(term -> !term.isEmpty())
+                .toList();
+    }
+
+    private static boolean matchesEveryTerm(Customer customer, List<String> terms) {
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    /** Strips accents and lower-cases, so that {@code Mäkinen} folds to {@code makinen}. */
+    private static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
