+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+
+class CustomerFilterTest {
+
+    private static final Customer ADA = new Customer(1, "Ada", "Aaltonen", "a@example.com", "Finland", CustomerStatus.ACTIVE);
+    private static final Customer JARNO = new Customer(2, "Jarno", "Mäkinen", "j@example.com", "Finland", CustomerStatus.PENDING);
+    private static final Customer JOSEPHINE = new Customer(3, "Joséphine", "Engberg", "e@example.com", "Denmark", CustomerStatus.CLOSED);
+
+    private static boolean matches(CustomerFilter filter, Customer customer) {
+        return filter.matcher().test(customer);
+    }
+
+    private static CustomerFilter named(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    @Test
+    void anEmptyOrBlankNameMatchesEveryCustomer() {
+        for (String name : new String[] {"", "   ", "\t"}) {
+            assertTrue(matches(named(name), ADA), "name: [" + name + "]");
+            assertTrue(matches(named(name), JARNO), "name: [" + name + "]");
+        }
+    }
+
+    @Test
+    void everyTermMustAppearInFirstOrLastName() {
+        assertTrue(matches(named("ada aal"), ADA));
+        assertTrue(matches(named("aal ada"), ADA));
+        assertFalse(matches(named("ada virtanen"), ADA));
+    }
+
+    @Test
+    void leadingTrailingAndRepeatedWhitespaceIsNotSignificant() {
+        assertTrue(matches(named("  ada \t  aal  "), ADA));
+    }
+
+    @Test
+    void caseIsIgnored() {
+        assertTrue(matches(named("ADA"), ADA));
+        assertTrue(matches(named("aaLTonen"), ADA));
+    }
+
+    @Test
+    void accentsAreIgnoredInBothDirections() {
+        assertTrue(matches(named("makinen"), JARNO));
+        assertTrue(matches(named("MAKINEN"), JARNO));
+        assertTrue(matches(named("mäkinen"), JARNO));
+        assertTrue(matches(named("josephine"), JOSEPHINE));
+        assertTrue(matches(named("Joséphine"), JOSEPHINE));
+        assertTrue(matches(named("Josephine"), JOSEPHINE));
+    }
+
+    @Test
+    void eachTermMayMatchEitherName() {
+        assertTrue(matches(named("ltonen"), ADA), "a substring of the last name");
+        assertTrue(matches(named("jos engb"), JOSEPHINE), "one term in the first name, one in the last");
+        assertTrue(matches(named("josephine engberg"), JOSEPHINE));
+        assertFalse(matches(named("jos nen"), JOSEPHINE), "no name contains nen");
+    }
+
+    @Test
+    void anEmptyStatusSetShowsEveryStatus() {
+        CustomerFilter any = new CustomerFilter("", Set.of());
+
+        assertTrue(matches(any, ADA));
+        assertTrue(matches(any, JARNO));
+        assertTrue(matches(any, JOSEPHINE));
+    }
+
+    @Test
+    void aStatusSetShowsOnlyThoseStatuses() {
+        CustomerFilter activeOrClosed = new CustomerFilter("", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));
+
+        assertTrue(matches(activeOrClosed, ADA));
+        assertFalse(matches(activeOrClosed, JARNO));
+        assertTrue(matches(activeOrClosed, JOSEPHINE));
+    }
+
+    @Test
+    void bothPartsMustMatch() {
+        CustomerFilter makinenActive = new CustomerFilter("makinen", Set.of(CustomerStatus.ACTIVE));
+
+        assertFalse(matches(makinenActive, JARNO), "Mäkinen is pending, not active");
+        assertFalse(matches(makinenActive, ADA), "Ada is active, but not named Mäkinen");
+    }
+
+    @Test
+    void noneMatchesEveryCustomer() {
+        assertTrue(matches(CustomerFilter.NONE, ADA));
+        assertTrue(matches(CustomerFilter.NONE, JARNO));
+        assertEquals("", CustomerFilter.NONE.name());
+        assertTrue(CustomerFilter.NONE.statuses().isEmpty());
+    }
+}
